-- ==============================================================================
-- SYNCHRONIZATION OF 1923 MASTER PRODUCT UNITS (PERSISTENT SNAPSHOT)
-- Target: Controlled One-Time Execution from Excel Reference
-- Batch ID: 'BATCH-20261110-EXCEL-SYNC'
-- ZERO lines deleted, ZERO foreign keys modified, ZERO batch/stock changes
-- ==============================================================================

BEGIN;

-- 1. Ensure persistent history and snapshot tables exist
CREATE TABLE IF NOT EXISTS public._sync_history (
  batch_id TEXT PRIMARY KEY,
  description TEXT NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  completed_at TIMESTAMPTZ,
  status TEXT NOT NULL CHECK (status IN ('running', 'completed', 'rolled_back', 'failed')),
  expected_row_count INTEGER NOT NULL,
  actual_row_count INTEGER
);

CREATE TABLE IF NOT EXISTS public._sync_product_unit_snapshots (
  id BIGSERIAL PRIMARY KEY,
  batch_id TEXT NOT NULL REFERENCES public._sync_history(batch_id) ON DELETE CASCADE,
  product_id UUID NOT NULL,
  product_unit_id UUID NOT NULL,
  old_unit_name TEXT,
  old_base_unit TEXT,
  old_unit_confirmed BOOLEAN,
  old_selling_price NUMERIC(14,2),
  old_is_active BOOLEAN,
  applied_unit_name TEXT NOT NULL,
  applied_selling_price NUMERIC(14,2),
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX IF NOT EXISTS idx_sync_snapshots_batch_prod
ON public._sync_product_unit_snapshots(batch_id, product_id);

-- 2. Precondition Assertions
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'product_units' AND column_name = 'is_active'
  ) THEN
    RAISE EXCEPTION 'PRECONDITION FAILED: Migration 0064 (is_active) must be applied before data sync.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public._sync_history
    WHERE batch_id = 'BATCH-20261110-EXCEL-SYNC' AND status = 'completed'
  ) THEN
    RAISE EXCEPTION 'PRECONDITION FAILED: Batch BATCH-20261110-EXCEL-SYNC has already completed.';
  END IF;
END $$;

-- 3. Register batch execution
VALUES ('BATCH-20261110-EXCEL-SYNC', 'Synchronize 1923 product units from Excel canonical master', 'running', 1923)
ON CONFLICT (batch_id) DO UPDATE SET status = 'running', started_at = clock_timestamp(), completed_at = NULL;

-- 4. Temporary staging table for incoming values
CREATE TEMP TABLE stage_product_sync (
  product_id UUID PRIMARY KEY,
  product_unit_id UUID,
  new_unit_name TEXT NOT NULL,
  new_selling_price NUMERIC(14,2)
) ON COMMIT DROP;


-- 5. Capture persistent pre-sync snapshot into public._sync_product_unit_snapshots
DELETE FROM public._sync_product_unit_snapshots WHERE batch_id = 'BATCH-20261110-EXCEL-SYNC';

  batch_id, product_id, product_unit_id,
  old_unit_name, old_base_unit, old_unit_confirmed,
  old_selling_price, old_is_active,
  applied_unit_name, applied_selling_price, created_at
)
SELECT
  'BATCH-20261110-EXCEL-SYNC',
  s.product_id,
  s.product_unit_id,
  pu.unit_name,
  p.base_unit,
  p.unit_confirmed,
  pu.selling_price,
  pu.is_active,
  s.new_unit_name,
  coalesce(s.new_selling_price, pu.selling_price),
  clock_timestamp()
FROM stage_product_sync s
JOIN public.product_units pu ON pu.id = s.product_unit_id
JOIN public.products p ON p.id = s.product_id;

-- 6. Apply updates with assertions
DO $$
DECLARE
  v_stage_count integer;
  v_snapshot_count integer;
  v_unit_updated integer;
  v_prod_updated integer;
BEGIN
  SELECT count(*) INTO v_stage_count FROM stage_product_sync;
  IF v_stage_count <> 1923 THEN
    RAISE EXCEPTION 'ASSERTION FAILED: Expected 1923 items in stage_product_sync, got %', v_stage_count;
  END IF;

  SELECT count(*) INTO v_snapshot_count
  FROM public._sync_product_unit_snapshots
  WHERE batch_id = 'BATCH-20261110-EXCEL-SYNC';

  IF v_snapshot_count <> 1923 THEN
    RAISE EXCEPTION 'ASSERTION FAILED: Expected 1923 snapshots captured, got %', v_snapshot_count;
  END IF;

  -- Update product_units without changing IDs or FK references
  UPDATE public.product_units pu
  SET unit_name = s.new_unit_name,
      selling_price = coalesce(s.new_selling_price, pu.selling_price),
      is_base_unit = true,
      updated_at = now()
  FROM stage_product_sync s
  WHERE pu.id = s.product_unit_id;
  GET DIAGNOSTICS v_unit_updated = ROW_COUNT;
  IF v_unit_updated <> 1923 THEN
    RAISE EXCEPTION 'ASSERTION FAILED: Expected 1923 product_units updated, got %', v_unit_updated;
  END IF;

  -- Update products table base_unit and unit_confirmed
  UPDATE public.products p
  SET base_unit = s.new_unit_name,
      unit_confirmed = true,
      updated_at = now()
  FROM stage_product_sync s
  WHERE p.id = s.product_id;
  GET DIAGNOSTICS v_prod_updated = ROW_COUNT;
  IF v_prod_updated <> 1923 THEN
    RAISE EXCEPTION 'ASSERTION FAILED: Expected 1923 products updated, got %', v_prod_updated;
  END IF;
END $$;

-- 7. Mark batch completed in tracking table
UPDATE public._sync_history
SET status = 'completed',
    completed_at = clock_timestamp(),
    actual_row_count = 1923
WHERE batch_id = 'BATCH-20261110-EXCEL-SYNC';

COMMIT;
